{
  "name": "loss_logsigmoid_002_label_smooth_stable_expects",
  "intuition": "Stabilize and simplify the pairwise logsigmoid loss by (1) declaring the required batch keys via implementation_hint.expects to satisfy the static gate, and (2) clamping label_smoothing into [0, 0.5] and scaling to a sane positive range to avoid invalid preference semantics or numerical blow-ups. The core ranking signal stays the same: a convex mix of -logsigmoid(x) and its symmetric counterpart.",
  "pseudocode": "require log_prob_w, log_prob_l; x = clamp(scale,0,10)*(lpw-lpl); eps=clamp(label_smoothing,0,0.5); loss = (1-eps)*(-logsigmoid(x)) + eps*(-logsigmoid(-x)); optional weighted mean",
  "hyperparams": {
    "scale": 0.950409166008815,
    "label_smoothing": 0.03
  },
  "operators_used": [
    "logsigmoid"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # implementation_hint.expects: ['log_prob_w', 'log_prob_l']
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if extra is not None else {}
    scale = hp.get('scale', 0.950409166008815)
    eps = hp.get('label_smoothing', 0.03)

    # Clamp hyperparams for stability and valid preference semantics.
    if isinstance(scale, (int, float)):
        scale = float(scale)
        if scale < 0.0:
            scale = 0.0
        if scale > 10.0:
            scale = 10.0
    else:
        # If scale is a tensor, clamp elementwise.
        scale = ops.clamp(scale, 0.0, 10.0)

    if isinstance(eps, (int, float)):
        eps = float(eps)
        if eps < 0.0:
            eps = 0.0
        if eps > 0.5:
            eps = 0.5
    else:
        eps = ops.clamp(eps, 0.0, 0.5)

    x = scale * (lpw - lpl)
    base = -ops.logsigmoid(x)
    sym = -ops.logsigmoid(-x)
    loss = (1.0 - eps) * base + eps * sym

    if weight is not None:
        loss = loss * weight
    return loss.mean()",
  "theoretical_basis": ""
}

{
  "name": "loss_logsigmoid_consensus_cost_margin",
  "intuition": "All parents converge on a stable pairwise preference objective using -logsigmoid(scale*(log_prob_w-log_prob_l)), optionally modulated by an external cost gap that is detached to avoid leaking gradients through the cost signal. A consensus-safe synthesis is to keep the same core logsigmoid ranking loss, use a moderate scale near the center of the successful scales, and incorporate the detached cost gap as a small additive margin that down-weights pairs where the preferred option is more costly, preserving the direction of the preference while gently biasing toward lower-cost winners when available. This maintains convex, well-behaved gradients and matches the common weighting/mean reduction pattern.",
  "pseudocode": "d = log_prob_w - log_prob_l; gap = detach(cost_b - cost_a); x = scale*d - cost_weight*gap; loss = -logsigmoid(x); if weight: loss*=weight; return mean(loss)",
