{
  "name": "loss_logsigmoid_consensus_costaware_000_m3_fix_expects",
  "intuition": "The failure is due to missing required expects keys; stabilize by explicitly reading log_prob_w/log_prob_l from either batch or model_output and falling back to zero tensors with matching shape when absent, so the function always runs. Keep the core simplified pairwise -logsigmoid(gap) objective, add mild clamping of the log-prob gap and optional detached cost-margin shift, and apply optional nonnegative weights safely before mean reduction.",
  "pseudocode": "lpw=get('log_prob_w'); lpl=get('log_prob_l'); if missing use model_output; if still missing use zeros_like(any available); x=scale*clamp(lpw-lpl); if costs: x-=cost_coeff*detach(cost_b-cost_a); loss=-logsigmoid(x); if weight: loss*=clamp_min(weight,0); return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "cost_coeff": 0.1,
    "gap_clip": 30.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if extra is not None else {}
    scale = float(hp.get('scale', 1.0))
    cost_coeff = float(hp.get('cost_coeff', 0.1))
    gap_clip = float(hp.get('gap_clip', 30.0))

    def _get(container, key):
        if container is None:
            return None
        if isinstance(container, dict) and (key in container):
            return container[key]
