    prefer_strict = bool(extra.get('prefer_strict', True))

    # winner has lower objective than loser (optionally with a minimum gap)
    if prefer_strict:
        base = objective[:, :, None] + gap_thr < objective[:, None, :]
    else:
        base = objective[:, :, None] <= objective[:, None, :] - gap_thr

    b_idx_all, w_all, l_all = base.nonzero(as_tuple=True)

    # Cap number of pairs per instance deterministically by keeping earliest pairs
    if b_idx_all.numel() == 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx_all, w_all, l_all), weight=None, meta={'builder': 'gap_capped_pairs', 'gap_threshold': gap_thr, 'max_pairs_per_instance': max_pairs_per_instance})

    keep = []
    for b in range(objective.shape[0]):
        m = (b_idx_all == b)
        if m.any():
            idx = m.nonzero(as_tuple=True)[0]
            if idx.numel() > max_pairs_per_instance:
                idx = idx[:max_pairs_per_instance]
            keep.append(idx)

    if len(keep) == 0:
        b_idx = b_idx_all[:0]
        w_idx = w_all[:0]
        l_idx = l_all[:0]
