            keep_idx = keep_idx.new_tensor(list(keep_idx.tolist()) + list(keep[i].tolist()))
        b_idx = b_idx_all[keep_idx]
        w_idx = w_all[keep_idx]
        l_idx = l_all[keep_idx]

