{
  "name": "builder_stratified_rank_cap_v2",
  "intuition": "Per instance, sort candidates by objective (lower is better) and emit a small, capped set of deterministic pairwise preferences: an anchor best-vs-worst, within-band adjacent comparisons in head/mid/tail rank bands, plus a few cross-band pairs (best-vs-mid, mid-vs-worst, best-vs-tail) to enforce separation while ensuring every instance contributes at least one pair.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape
    device = objective.device

    # Avoid Python builtins (e.g., int) since the sandbox may restrict them.
    def _to_i(x, default):
        if x is None:
            return default
        if hasattr(x, 'item'):
            return x.item()
        return x

    extra_dict = extra if isinstance(extra, dict) else {}

    cap = _to_i(extra_dict.get('pairs_per_instance', 8), 8)
    if cap < 1:
        cap = 1

    order = objective.argsort(dim=1)

    head_n = _to_i(extra_dict.get('head_n', 2), 2)
    tail_n = _to_i(extra_dict.get('tail_n', 2), 2)
    if head_n < 1:
        head_n = 1
    if tail_n < 1:
        tail_n = 1
    if head_n > K:
        head_n = K
    if tail_n > K:
        tail_n = K

    mid_n = _to_i(extra_dict.get('mid_n', 2), 2)
    if mid_n < 1:
        mid_n = 1
    if mid_n > K:
        mid_n = K

    mid_center = K // 2
    mid_start = mid_center - (mid_n // 2)
    if mid_start < 0:
        mid_start = 0
    if mid_start + mid_n > K:
        mid_start = K - mid_n

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        ord_b = order[b]
        used = {}

        def add_pair(wi, li):
            # Avoid self-pairs and duplicates.
            if wi == li:
                return
            wi_i = wi.item() if hasattr(wi, 'item') else wi
            li_i = li.item() if hasattr(li, 'item') else li
            key = (wi_i, li_i)
            if key in used:
                return
            used[key] = 1
            b_list.append(b)
            w_list.append(wi_i)
            l_list.append(li_i)

        # 1) Always at least one pair: best vs worst.
        add_pair(ord_b[0], ord_b[-1])

        # 2) Within-band adjacent comparisons.
        # head chain
        head_end = head_n - 1
        if head_end > K - 1:
            head_end = K - 1
        for i in range(0, head_end):
            add_pair(ord_b[i], ord_b[i + 1])
        # tail chain
        tail_start = K - tail_n
        if tail_start < 0:
            tail_start = 0
        for i in range(tail_start, K - 1):
            add_pair(ord_b[i], ord_b[i + 1])
        # mid chain
        mid_end = mid_start + mid_n - 1
        if mid_end > K - 1:
            mid_end = K - 1
        for i in range(mid_start, mid_end):
            add_pair(ord_b[i], ord_b[i + 1])

        # 3) Cross-band comparisons.
        add_pair(ord_b[0], ord_b[mid_center])
        add_pair(ord_b[mid_center], ord_b[-1])
        for t in range(tail_start, K):
            add_pair(ord_b[0], ord_b[t])

        # Enforce per-instance cap deterministically.
        if len(used) > cap:
            keep = cap
            new_b_list = []
            new_w_list = []
            new_l_list = []
            cnt = 0
            for bi, wi, li in zip(b_list, w_list, l_list):
                if bi != b:
                    new_b_list.append(bi)
                    new_w_list.append(wi)
                    new_l_list.append(li)
                else:
                    if cnt < keep:
                        new_b_list.append(bi)
                        new_w_list.append(wi)
                        new_l_list.append(li)
                        cnt += 1
            b_list = new_b_list
            w_list = new_w_list
            l_list = new_l_list

    b_idx = torch.tensor(b_list, device=device, dtype=torch.long)
    winner_idx = torch.tensor(w_list, device=device, dtype=torch.long)
    loser_idx = torch.tensor(l_list, device=device, dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'stratified_rank_cap',
            'pairs_per_instance': cap,
            'head_n': head_n,
            'mid_n': mid_n,
            'tail_n': tail_n
        }
    )
