{
  "name": "builder_rank_strata_no_int",
  "intuition": "Create deterministic per-instance preferences from objective ranks (lower is better): best-vs-next, head-vs-tail for strong signal, and adjacent mid-vs-mid for local ordering, while avoiding Python builtins like int and ensuring at least one pair and full coverage per instance.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape

    max_pairs = extra.get('max_pairs_per_instance', 64)
    if max_pairs is None:
        max_pairs = 64
    if max_pairs < 1:
        max_pairs = 1

    k = extra.get('stratum_k', 3)
    if k is None:
        k = 3
    if k < 1:
        k = 1
    if k > N:
        k = N

    mid_k = extra.get('mid_k', None)
    if mid_k is None:
        mid_k = N // 4
        if mid_k < 1:
            mid_k = 1
        if mid_k > k:
            mid_k = k
    if mid_k < 1:
        mid_k = 1
    if mid_k > N:
        mid_k = N

    order = objective.argsort(dim=1)  # best first

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        ord_b = order[b]

        head = ord_b[:k]
        tail = ord_b[-k:]

        mid_start = (N // 2) - (mid_k // 2)
        if mid_start < 0:
            mid_start = 0
        mid_end = mid_start + mid_k
        if mid_end > N:
            mid_end = N
        mid = ord_b[mid_start:mid_end]
        if mid.numel() == 0:
            mid = ord_b[:1]

        pairs_w = []
        pairs_l = []

        # 1) Best vs near-best
        if head.numel() >= 2:
            w0 = head[0]
            for j in range(1, head.numel()):
                pairs_w.append(w0)
                pairs_l.append(head[j])

        # 2) Head vs tail
        for i in range(head.numel()):
            wi = head[i]
            for j in range(tail.numel()):
                lj = tail[j]
                pairs_w.append(wi)
                pairs_l.append(lj)

        # 3) Mid vs mid adjacent
        if mid.numel() >= 2:
            for j in range(mid.numel() - 1):
                pairs_w.append(mid[j])
                pairs_l.append(mid[j + 1])

        # Deduplicate deterministically without Python sets (keep first occurrence)
        uniq_w = []
        uniq_l = []
        for idx in range(len(pairs_w)):
            w = pairs_w[idx]
            l = pairs_l[idx]
            if w == l:
                continue
            dup = False
            for t in range(len(uniq_w)):
                if uniq_w[t] == w and uniq_l[t] == l:
                    dup = True
                    break
            if dup:
                continue
            uniq_w.append(w)
            uniq_l.append(l)
            if len(uniq_w) >= max_pairs:
                break

        # Fallback: ensure at least one pair if possible
        if len(uniq_w) == 0 and N >= 2:
            uniq_w = [ord_b[0]]
            uniq_l = [ord_b[-1]]

        for idx in range(len(uniq_w)):
            b_list.append(b)
            w_list.append(uniq_w[idx])
            l_list.append(uniq_l[idx])

    b_idx = objective.new_tensor(b_list, dtype=torch.long)
    winner_idx = objective.new_tensor(w_list, dtype=torch.long)
    loser_idx = objective.new_tensor(l_list, dtype=torch.long)

    # Ensure 1D int64 tensors with consistent lengths
    b_idx = b_idx.reshape(-1).to(dtype=torch.long)
    winner_idx = winner_idx.reshape(-1).to(dtype=torch.long)
    loser_idx = loser_idx.reshape(-1).to(dtype=torch.long)

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'rank_strata_no_int', 'k': k, 'mid_k': mid_k, 'max_pairs_per_instance': max_pairs})
"
}

