            continue
        obj = objective[b]
        sorted_idx = obj.argsort()

        kk = k
        try:
            if kk > N:
                kk = N
        except Exception:
            kk = N

        best_idx = sorted_idx[:kk]
        worst_idx = sorted_idx[-kk:]

