    k = per_instance_cap

    winner_idx = order[:, :k].reshape(-1).to(dtype=torch.long)
    loser_idx = order[:, 1:(k + 1)].reshape(-1).to(dtype=torch.long)
    b_idx = torch.arange(B, device=objective.device, dtype=torch.long).unsqueeze(1).expand(B, k).reshape(-1)

    if not use_weights:
        weight = None
    else:
        # Compute objective gaps for each adjacent pair; larger gaps get weight closer to 1.
        obj_sorted = objective.gather(1, order)
        gap = (obj_sorted[:, 1:(k + 1)] - obj_sorted[:, :k]).reshape(-1)
