    # This strategy only uses rank-adjacent pairs (r, r+1), so r in [0, N-2].
    if per_cap > (N - 1):
        per_cap = N - 1

    order = objective.argsort(dim=1)  # best (lowest objective) first

    # Build candidate rank positions r where we add pair (r, r+1).
    r0 = objective.new_zeros((1,), dtype=torch.long)

    if N >= 3:
