        r_mid = r0

    r_tail = objective.new_full((1,), N - 2, dtype=torch.long)

    rs = [r0]
    if per_cap >= 2 and N >= 3:
        rs.append(r_mid)
    if per_cap >= 3 and N >= 3:
        rs.append(r_tail)

    remaining = per_cap - torch.as_tensor(rs).numel()
    if remaining > 0 and (N - 1) > 0:
        denom = objective.new_full((1,), remaining + 1, dtype=torch.long)
        for t in range(1, remaining + 1):
