  "intuition": "Stabilize the pairwise logistic loss by (1) explicitly declaring the required batch keys in implementation_hint.expects, (2) clamping label_smooth into [0, 0.5] and forcing a finite positive scale, and (3) computing the label-smoothed objective via softplus on a clamped logit-difference to avoid extreme logits producing inf/NaN while preserving the original preference semantics (winner should have higher log_prob).",
  "pseudocode": "x = clamp(scale*(lpw-lpl), -clip, clip); loss = (1-eps)*softplus(-x) + eps*softplus(x); return mean(weight*loss)",
  "hyperparams": {
    "scale": 1.1517436613227505,
    "label_smooth": 0.05,
    "logit_clip": 30.0
  },
  "operators_used": [
    "softplus"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l"
    ],
    "returns": "loss",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {})
    scale = hp.get('scale', 1.1517436613227505)
    eps = hp.get('label_smooth', 0.05)
    clip = hp.get('logit_clip', 30.0)

    # Make hyperparams numerically safe.
    try:
        scale = float(scale)
    except Exception:
        scale = 1.1517436613227505
    if not (scale > 0.0):
        scale = 1.1517436613227505

    try:
        eps = float(eps)
    except Exception:
        eps = 0.05
    if eps < 0.0:
        eps = 0.0
    if eps > 0.5:
        eps = 0.5

    try:
        clip = float(clip)
    except Exception:
        clip = 30.0
    if not (clip > 0.0):
        clip = 30.0

    x = scale * (lpw - lpl)
    x = ops.clamp(x, -clip, clip)

    # Label-smoothed logistic preference loss, implemented with softplus for stability:
    # softplus(-x) = -log(sigmoid(x)), softplus(x) = -log(sigmoid(-x))
    loss_pos = ops.softplus(-x)
    loss_neg = ops.softplus(x)
    loss = (1.0 - eps) * loss_pos + eps * loss_neg

    if weight is not None:
        loss = loss * weight

    return loss.mean()",
  "theoretical_basis": "Bradley-Terry pairwise logistic loss with label smoothing; softplus-based form improves numerical stability while keeping the same preference directionality."
}

